function lobby(){const d=chosen(ui.deckId),resume=read('artifact.match',null);return `<main class="lobby"><div class="lobby-ambient" style="background-image:url('${C.drow_ranger.art}')"></div><div class="lobby-inner"><div class="eyebrow"><span></span> THREE LANES. ONE VICTORY. <span></span></div><h1>ARTIFACT</h1><p class="lobby-sub">${T('三 路 战 场','T H R E E F O L D')}</p><div class="lobby-heroes">${d.heroes.map((k,i)=>`<div class="lobby-hero" style="--i:${i}">${cardHTML(k,{small:true})}<span class="deploy-badge">${i<3?T('首发','Starting'):T('第 '+(i-1)+' 回合','Round '+(i-1))}</span></div>`).join('')}</div><div class="match-setup"><label>${T('你的牌组','Your deck')}<select id="deck-select">${allDecks().map(x=>`<option value="${x.id}" ${x.id===ui.deckId?'selected':''}>${esc(pick(x,'name'))} · ${x.heroes.map(k=>C[k].color).filter((v,i,a)=>a.indexOf(v)===i).map(CN).join(' / ')}</option>`).join('')}</select></label><div class="versus">VS</div><label>${T('练习对手','Practice opponent')}<select id="opponent-select">${presets.map(x=>`<option value="${x.id}" ${x.id===ui.opponentId?'selected':''}>${esc(pick(x,'name'))} · ${T('电脑','AI')}</option>`).join('')}</select></label></div><div class="lobby-actions">${button('start',`${icon('sword')} ${T('开始对战','Start match')}`,'primary large')}${resume&&resume.winner===null?button('resume',T('继续上次对局','Resume last match'),'secondary large'):''}<a class="secondary large" href="online.html">${T('匹配码联机','Play online with a code')}</a></div><div class="lobby-note">${T('5 位英雄 · 三路攻防 · 回合商店','5 heroes · three lanes · a shop each round')} <span>${T('耳机体验更佳','Best with headphones')}</span></div><footer class="lobby-footer"><span>${T('非官方前端重制 · 本地单人练习','Unofficial fan remake · offline practice')}</span>${button('about',T('资料来源与还原说明','Sources & scope'),'text-button')}</footer></div></main>`;}
function validUnit(u){const sel=ui.selection,s=sel?.spec[sel.targets.length];if(!s||s.kind!=='unit')return false;return game.selectable(u)&&(s.cross||u.lane===game.s.lane)&&(s.side!=='ally'||u.owner===0)&&(s.side!=='enemy'||u.owner===1)&&(!s.hero||u.hero)&&(!s.creep||!u.hero)&&(!s.color||C[u.k].color===s.color)&&(!s.other||u.uid!==sel.id)&&!sel.targets.includes(u.uid);}
