function heroSkillDetails(u){return heroSkills(u).map(a=>{const key=a.k||u.k,active=game.abilities(u).find(v=>v.k===key),blocked=a.type==='active'?abilityBlocked(u,active||{k:key,remaining:0}):'';return `<section class="hero-skill-detail"><div class="hero-skill-heading">${a.type!=='none'?`<img src="${esc(a.icon||C[u.k].art)}" alt="">`:''}<div><strong>${esc(ABNAME(a))}</strong><small>${a.type==='active'?T('主动 · 冷却 '+a.cooldown+' 回合','Active · Cooldown '+a.cooldown):a.type==='passive'?T('被动 · 自动触发','Passive · triggers automatically'):T('本体属性','Innate')}</small></div></div><p>${esc(ABDESC(a))}</p>${a.type==='active'?button('activate',esc(blocked||T('使用 ','Use ')+ABNAME(a)),'ability-button',`data-id="${u.uid}" data-key="${key}" ${blocked?'disabled':''}`):a.type==='passive'?`<small class="passive-explanation">${!game.enabled(u)?T('当前失效：阵亡、沉默或眩晕','Inactive while dead, silenced or stunned'):T('满足描述条件时自动生效，无需出牌或点击施放。','Triggers automatically when its conditions are met — no click required.')}</small>`:''}</section>`;}).join('');}
