function laneHTML(l){const pending=game.s.phase==='deploy'&&!online?.isSpectator()?getDeploymentPlan().ready.filter(u=>getDeploymentPlan().lane(u.uid)===l):[];const s=game.s,f=s.phase==='action'&&l>=s.lane?game.combatForecast(l):{tower:[0,0],units:{}},baseCount=Math.max(1,...game.all(null,l).map(u=>u.pos+1),...(s.jex||[]).filter(j=>j.lane===l).map(j=>j.pos+1)),count=baseCount+pending.length+(ui.selection?.spec[ui.selection.targets.length]?.kind==='position'?1:0),sel=ui.selection?.spec[ui.selection.targets.length],isPos=sel?.kind==='position'&&(sel.cross||l===s.lane),laneTargetable=sel?.kind==='lane'&&(!game.validLaneTarget||game.validLaneTarget(ui.selection.k,0,l)),legalPositions=isPos?game.positionTargets(0,l,sel):[],displayPositions=[...(legalPositions.includes(-1)?[-1]:[]),...Array.from({length:count},(_,i)=>i)];const row=p=>`<div class="unit-row ${p?'enemy':'ally'}">${displayPositions.map(pos=>{const u=game.at(p,l,pos);return `<div class="slot ${p===0&&isPos&&legalPositions.includes(pos)&&(sel.occupied||!u)?'targetable':''}" data-slot="${pos}" data-lane="${l}" data-owner="${p}">${(s.jex||[]).filter(j=>j.owner===p&&j.lane===l&&j.pos===pos).map(j=>`<span class="jex-marker ${j.enhanced?'enhanced':''}" title="${T('杰克斯：下一张己方技能牌后','Jex: after your next spell, ')}${j.enhanced?T('造成3伤害并翻牌','deal 3 damage and flip'):T('造成2伤害并缴械','deal 2 damage and disarm')}"><img src="assets/dota2/dark_willow_bedlam.png" alt="Jex"><b>${j.enhanced?T('恐吓','Menace'):T('作祟','Hijinks')}</b><small>${T('等待技能牌','Awaiting spell')}</small></span>`).join('')}${u?unitHTML(u,f)+(s.mines||[]).filter(m=>m.unit===u.uid&&(m.owner===0||online?.isSpectator())).map(()=>`<span class="mine-marker" title="${T('感应地雷 · 被敌方卡牌或技能选中、携带者死亡、或被活性电击命中时自动引爆','Proximity Mine · automatically detonates when targeted by an enemy card or ability, when its carrier dies, or when struck by Reactive Tazer')}"><img src="assets/dota2/techies_proximity_mines.png" alt="${T('感应地雷','Proximity Mine')}"><b>${T('雷','MINE')}</b></span>`).join('')+(game.flag(u,'cookie')?`<span class="cookie-marker" title="${T('饼干标记 · 持续至回合结束，可被莫蒂默之吻吐向目标分路','Cookie marker · lasts until end of round; Mortimer Kisses can spit it into the target lane')}"><img src="assets/dota2/snapfire_firesnap_cookie.png" alt="${T('饼干','Cookie')}"><b>${T('饼','🍪')}</b></span>`:''):p===0&&pending[pos-baseCount]?deployPreviewHTML(pending[pos-baseCount],l):`<div class="empty-slot">${p===0&&isPos&&legalPositions.includes(pos)?'+':'·'}</div>`}</div>`;}).join('')}</div>`;
 const arrow=(p,u)=>{const t=game.target(u),d=t?t.pos-u.pos:0,x=48*(u.pos+.5),end=48*((t?t.pos:u.pos)+.5);return `<path d="M ${x} ${p?4:46} Q ${x} 25 ${end} ${p?40:10}" class="attack-path ${p?'dire-path':'radiant-path'} ${game.flag(u,'disarm')||game.flag(u,'stun')?'disabled-path':''}" marker-end="url(#arrow-${l}-${p})"/>`;};
 return `<section class="lane ${l===s.lane?'active-lane':''} ${laneTargetable?'lane-target':''}" data-lane="${l}" ${ui.focus!==null&&ui.focus!==l?'inert aria-hidden="true"':''}><div class="terrain-light" aria-hidden="true"></div><div class="scene-deck" aria-hidden="true"><span>▽</span></div><img class="scene-imp" src="assets/scene/blue-imp.png" alt="" aria-hidden="true"><div class="river-light" aria-hidden="true"></div><div class="lane-heading"><span class="lane-number">0${l+1}</span><h2>${LN(l)}</h2><span class="lane-state">${s.phase==='shop'?T('战斗结束','Resolved'):s.phase==='deploy'?T('部署阶段','Deploying'):l<s.lane?T('已结算','Resolved'):l===s.lane?T('当前战线','Active lane'):T('等待推进','Pending')}</span>${button('focus-lane',icon('expand'),'icon-button',`data-lane="${l}" title="${T('聚焦战线','Focus lane')}" aria-label="${T('聚焦','Focus ')}${LN(l)}"`)}</div>${towerHTML(1,l,f)}${improvements(1,l)}<div class="lane-scroll"><div class="lane-units" style="--slots:${displayPositions.length};--slot-width:${ui.focus!==null?'116px':'76px'}">${row(1)}<div class="battle-arrows"><svg viewBox="0 0 ${count*48} 50" preserveAspectRatio="none" aria-hidden="true"><defs>${[0,1].map(p=>`<marker id="arrow-${l}-${p}" markerWidth="4" markerHeight="4" refX="3" refY="2" orient="auto"><path d="M0 0 L4 2 L0 4" fill="${p?'#c7796b':'#93b5a0'}"/></marker>`).join('')}</defs>${game.all(null,l).map(u=>arrow(u.owner,u)).join('')}</svg><span class="lane-word">${l===s.lane?'COMBAT':'ARTIFACT'}</span></div>${row(0)}</div></div>${improvements(0,l)}${towerHTML(0,l,f)}${s.phase==='deploy'&&!online?.isSpectator()?`<div class="deploy-lane-target" data-deploy-lane="${l}">${button('assign-deploy',ui.deploySelected?T('安排 ','Assign ')+cardName(C[game.get(ui.deploySelected).k])+' → '+LN(l):T('拖动英雄到','Drag a hero to ')+LN(l),'deploy-lane-button',`data-lane="${l}" ${ui.deploySelected?'':'disabled'}`)}<span>${T('现有','Yours')} ${game.all(0,l).length} · ${T('预分路','Planned')} ${pending.length} / ${T('敌方','Enemy')} ${game.all(1,l).length}</span></div>`:''}${laneTargetable?button('target-lane',T('选择','Select ')+LN(l),'lane-select-button',`data-lane="${l}"`):''}</section>`;
}
function roster(p){return `<div class="roster">${game.s.players[p].heroes.map(k=>{const u=game.s.units.find(u=>u.owner===p&&u.k===k&&!u.copy),dead=!u?.alive,ready=dead&&u.readyRound<=game.s.round;return `<button class="roster-hero ${dead?'at-fountain':''} ${ready?'ready':''}" data-action="roster" data-id="${u?.uid}" data-card="${k}" title="${esc(cardName(C[k]))} · ${dead?(bridge?T('本关阵亡，不会复活','Dead for this stage'):T('泉水 · 第 ','Fountain · back on round ')+u.readyRound):LN(u.lane)}"><img src="${C[k].art}" alt="${esc(cardName(C[k]))}"><span>${dead?(bridge?T('阵亡','Dead'):ready?T('就绪','Ready'):u.readyRound-game.s.round):['Ⅰ','Ⅱ','Ⅲ'][u.lane]}</span></button>`;}).join('')}</div>`;}
function selectionText(){if(!ui.selection)return '';const se=ui.selection,s=se.spec[se.targets.length],label=!s?T('拖到当前战线释放','Drag onto the active lane'):s.kind==='lane'?T('选择目标战线','Choose a target lane'):s.kind==='position'?(s.occupied?T('选择己方位置；放在荆棘上可强化杰克斯','Choose a friendly slot — placing on Brambles empowers Jex'):T('选择亮起的空白位置','Choose a highlighted slot')):s.kind==='improvement'?T('选择一个场上强化','Choose an improvement in play'):T(`选择${s.side==='ally'?'友方':s.side==='enemy'?'敌方':''}${s.hero?'英雄':s.creep?'小兵':'单位'}${s.cross?'（可跨路）':''}`,`Choose ${s.side==='ally'?'a friendly':s.side==='enemy'?'an enemy':'a'} ${s.hero?'hero':s.creep?'creep':'unit'}${s.cross?' (any lane)':''}`);return `<div class="selection-banner">${icon('bolt')}<strong>${cardName(C[se.k])}</strong><span>${label} ${se.spec.length>1?`· ${se.targets.length+1}/${se.spec.length}`:''}</span>${button('cancel',T('取消 · Esc','Cancel · Esc'),'text-button')}</div>`;}
function battle(){const s=game.s,fronts=Array.from({length:s.activeLanes||3},(_,i)=>i),p=s.players[0],e=s.players[1],sel=ui.selection;return `<main class="battle-screen ${ui.focus!==null?'lane-focused':''} ${s.phase==='deploy'?'planning-deployment':''}"><div class="table-environment" aria-hidden="true"><div class="astrolabe"></div>${[0,1,2,3].map(i=>`<div class="candle candle-${i}"><i></i></div>`).join('')}</div><div class="enemy-hand" aria-label="${T('对手手牌 '+e.hand.length+' 张','Enemy hand · '+e.hand.length+' cards')}">${Array.from({length:Math.min(e.hand.length,12)},(_,i)=>`<span class="card-back" style="--fan:${i-(Math.min(e.hand.length,12)-1)/2}"></span>`).join('')}</div><div class="match-strip"><div class="opponent-block"><span class="faction dire">${T('夜魇','Dire')}</span>${roster(1)}<div class="player-meta"><strong>${esc(L(e.name))}</strong><small>${online?T('真人对手 · 实时联机','Human opponent · live online'):bridge?T('按预告和攻击箭头行动','Follow the previews and attack arrows'):`${T('电脑对手','AI opponent')} · ${T('手牌','hand')} ${e.hand.length} · ${T('牌库','deck')} ${e.deck.length}`}</small></div></div><div class="round-indicator"><small>ROUND</small><strong>${String(s.round).padStart(2,'0')}</strong></div><div class="phase-track">${(bridge?fronts.map(LN):[LN(0),LN(1),LN(2),T('商店','Shop')]).map((n,i)=>`<span class="${s.phase==='shop'&&i===3||s.phase!=='shop'&&s.lane===i?'current':''} ${s.lane>i?'done':''}">${i===3?icon('coin'):'0'+(i+1)} ${n}</span>`).join('')}</div><div class="enemy-gold">${icon('coin')}${e.gold}</div></div>${online?online.status():bridge?bridge.status(game):''}${selectionText()}<nav class="board-navigation" aria-label="${T('战场镜头','Battlefield camera')}">${button('unfocus',(bridge?fronts.length+T('路总览','-lane overview'):T('三路总览','All lanes')),'view-button '+(ui.focus===null?'selected':''),'aria-pressed="'+(ui.focus===null)+'"')}${fronts.map(l=>button('focus-lane',`<span>${LN(l)}</span><span class="mini-towers"><b>♜ ${s.lanes[l].towers[1].hp}</b><b>♜ ${s.lanes[l].towers[0].hp}</b></span><small>${s.phase==='action'&&s.lane===l?T('行动中','In combat'):s.phase==='shop'?T('已结算','Resolved'):l<s.lane?T('已结算','Resolved'):T('待行动','Waiting')}</small>`,'view-button '+(ui.focus===l?'selected':''),`data-lane="${l}" aria-pressed="${ui.focus===l}"`)).join('')}<span>${T('1 / 2 / 3 聚焦 · 0 总览','1 / 2 / 3 focus · 0 overview')}</span></nav><div class="camera-gesture-hint">${ui.focus===null?T('点击战线放大 · 双击空白切换视角','Click a lane to zoom · double-click empty space to change view'):T('双击棋盘空白返回三路总览','Double-click empty board space for the three-lane overview')}</div><div class="camera-label">${ui.focus===null?(bridge?fronts.length+T(' 路 战 场','-L A N E S'):T('三 路 战 场','T H R E E F O L D')):LN(ui.focus)+' · '+T('第 '+s.round+' 回合','Round '+s.round)}</div><div class="board-viewport"><div class="board ${ui.focus!==null?'focused-board':''}" style="--focus:${ui.focus??0};--front-count:${fronts.length}">${fronts.map(laneHTML).join('')}</div></div>${ui.focus!==null?`<button class="camera-prev" data-action="focus-lane" data-lane="${Math.max(0,ui.focus-1)}" aria-label="${T('上一条战线','Previous lane')}" ${ui.focus===0?'disabled':''}>‹</button><button class="camera-next" data-action="focus-lane" data-lane="${Math.min(fronts.length-1,ui.focus+1)}" aria-label="${T('下一条战线','Next lane')}" ${ui.focus===fronts.length-1?'disabled':''}>›</button>`:''}<div class="bottom-strip"><div class="friendly-block"><span class="faction radiant">${T('天辉','Radiant')}</span>${roster(0)}<div class="player-meta"><strong>${esc(L(p.name))}</strong><small>${p.deck.length} ${T('张牌库','in deck')} · ${p.discard.length} ${T('张弃牌','discarded')}</small></div></div><div class="gold-balance">${icon('coin')}<strong>${p.gold}</strong><span>${T('金币','Gold')}</span></div><div class="turn-status"><span class="initiative-coin ${s.initiative===0?'ours':''}" title="${T('下一战线先手','Initiative next lane')}">Ⅰ</span><span>${online?.isSpectator()?(s.phase==='deploy'?T('双方正在安排分路','Both sides are deploying'):s.phase==='shop'?T('双方正在购物','Both sides are shopping'):s.phase==='ended'?T('对局结束','Match over'):(s.turn===0?T('天辉','Radiant'):T('夜魇','Dire'))+T('正在行动',' is acting')):s.phase==='deploy'?T('选择英雄部署的战线','Choose a lane to deploy your heroes'):s.phase==='shop'?T('购物阶段','Shopping phase'):s.winner!==null?T('对局结束','Match over'):ui.busy?T('战场结算中…','Resolving combat…'):s.turn===0?T('轮到你行动','Your move'):T('对手正在思考…','Opponent is thinking…')}<small>${s.passes===1?T('对方已让过，再让过将结算战斗','Opponent passed — passing again resolves combat'):T('先手权：','Initiative: ')+(s.initiative===0?T('天辉','Radiant'):T('夜魇','Dire'))}</small></span></div>${ui.focus!==null?button('unfocus',(bridge?fronts.length+T('路总览','-lane overview'):T('三路总览','All lanes')),'secondary'):''}<div class="pass-area">${button('pass',`<img class="pass-medallion" src="assets/pass-medallion.svg" alt="" draggable="false"><span class="pass-label">${s.passes===1?T('战斗','Combat'):T('让过','Pass')}</span>`,'pass-button '+(s.passes===1?'combat-ready':''),`aria-label="${s.passes===1?T('进行战斗','Start combat'):T('让过','Pass')}" title="${s.passes===1?T('双方让过，结算当前战线','Both passed — resolve this lane'):T('让过行动','Pass your action')} · ${T('空格键','Spacebar')}" id="pass-button" ${s.turn!==0||s.phase!=='action'||ui.busy?'disabled':''}`)}<small>${T('空格键','Spacebar')} · ${s.passes===1?T('结算当前战线','resolve this lane'):T('保留行动选择','keep acting')}</small></div></div><div class="hand-zone"><div class="hand-label">${icon('cards')}<strong>${T('手牌','Hand')}</strong><span>${p.hand.length}</span></div><button class="hand-page hand-prev" data-action="hand-prev" aria-label="${T('向前浏览手牌','Scroll hand forward')}">‹</button><button class="hand-page hand-next" data-action="hand-next" aria-label="${T('向后浏览手牌','Scroll hand back')}">›</button><div class="hand-scroll"><div class="hand-cards">${online?.isSpectator()?`<p class="spectator-hand-note">${T('实时观战 · 双方手牌保密，可点击单位查看详情','Spectating live — both hands are hidden; click units for details')}</p>`:p.hand.map((h,i)=>`<div class="hand-wrap" style="--card-index:${i};--fan:${Math.max(-4,Math.min(4,i-(p.hand.length-1)/2))}">${cardHTML(h.k,{hand:h,small:true})}</div>`).join('')}${!p.hand.length?`<p class="empty-hand">${T('手中暂无卡牌。下回合会抽取新牌。','No cards in hand. New cards are drawn next round.')}</p>`:''}</div></div><div class="hand-tools">${button('log',icon('book'),'icon-button',`title="${T('战斗记录','Battle log')}" aria-label="${T('战斗记录','Battle log')}"`)}${button('save-match',icon('save'),'icon-button',`title="${T('保存对局','Save match')}" aria-label="${T('保存对局','Save match')}"`)}${button('surrender',T('认输','Concede'),'text-button')}</div></div><div class="action-tip">${sel?T('点击亮起的目标以完成出牌','Click a highlighted target to finish the card'):T('双击手牌或拖到战场出牌 · 单击仅查看 · 点击单位查看技能 · 悬停查看卡牌 · 按 Esc 取消','Double-click or drag a card to play · single-click inspects · click a unit for abilities · hover for details · Esc cancels')}</div>${s.phase==='shop'?shopHTML():s.phase==='deploy'?deployHTML():s.phase==='ended'&&!ui.busy?endHTML():''}${ui.inspect?inspectorHTML():''}${(ui.lastEnemyCast||ui.lastCast)?`<button class="last-cast" data-action="card-info" data-key="${(ui.lastEnemyCast||ui.lastCast).card}" title="${esc(L((ui.lastEnemyCast||ui.lastCast).text))}"><small>${ui.lastEnemyCast?T('对方上一张牌','Opponent\'s last card'):T('上一行动','Last action')} · ${(ui.lastEnemyCast||ui.lastCast).owner?T('夜魇','Dire'):T('天辉','Radiant')}</small><strong>${esc((ui.lastEnemyCast||ui.lastCast).label||(C[(ui.lastEnemyCast||ui.lastCast).card]?cardName(C[(ui.lastEnemyCast||ui.lastCast).card]):''))}</strong><span>${esc(L((ui.lastEnemyCast||ui.lastCast).text))}</span></button>`:''}<div id="cast-status" class="sr-only" role="status" aria-live="polite">${esc(L((ui.lastEnemyCast||ui.lastCast)?.text||''))}</div><div id="fx-layer" aria-hidden="true"></div>${ui.intro?introHTML():''}</main>`;}
function introHTML(){return `<div class="versus-intro"><div class="versus-stars"></div><div class="intro-side enemy"><span>${esc(L(game.s.players[1].name))}</span><div>${game.s.players[1].heroes.map(k=>cardHTML(k,{small:true})).join('')}</div></div><div class="artifact-sigil">▽</div><div class="intro-side ally"><div>${game.s.players[0].heroes.map(k=>cardHTML(k,{small:true})).join('')}</div><span>${esc(L(game.s.players[0].name))}</span></div>${button('skip-intro',T('进入战场 · 点击跳过','Enter the battlefield · click to skip'),'intro-skip')}</div>`;}
function shopHTML(){if(online?.isSpectator())return '';if(ui.busy)return '';const pl=game.s.players[0],s=pl.shop;if(ui.shopHidden)return `<div class="shop-return">${button('toggle-shop',T('返回商店 · ','Back to shop · ')+pl.gold+' '+T('金币','gold'),'secondary')}${button('finish-shop',T('完成购物','Done shopping'),'primary')}</div>`;return `<div class="phase-overlay"><section class="shop-panel" role="dialog" aria-modal="true" aria-label="${T('回合商店','Round shop')}"><div class="shop-eye" aria-hidden="true"><i></i></div><div class="shop-heading"><div><div class="eyebrow">THE SECRET SHOP</div><h2>${T('神秘商店','The Secret Shop')}</h2><p>${T('为下一轮战斗做好准备。','Stock up for the next round of combat.')}</p></div><div class="shop-gold">${icon('coin')}<strong>${pl.gold}</strong><span>${T('可用金币','Gold available')}</span></div></div><div class="shop-stalls">${[['secret',T('神秘商品','Secret item'),T('本轮限购一次','One per round')],['deck',T('物品牌组','Item deck'),T('购买后展示下一件','Reveals the next item')],['consumable',T('消耗品','Consumable'),T('本轮限购一次','One per round')]].map(([slot,label,desc])=>{const k=s[slot],c=C[k],sold=slot==='secret'&&s.secretBought||slot==='consumable'&&s.consumed||!k,price=slot==='secret'&&pl.freeShop?0:c?.gold;return `<div class="shop-stall ${sold?'sold':''}"><span class="stall-label">${label}</span>${c?cardHTML(k,{small:true,shop:true}):`<div class="sold-placeholder">${T('物品牌组已售罄','Item deck sold out')}</div>`}<p>${desc}</p>${button('buy',sold?T('已售罄','Sold out'):`${icon('coin')} ${price} · ${T('购买','Buy')}`,sold?'secondary':'primary',`data-slot="${slot}" ${sold||pl.gold<price?'disabled':''}`)}${slot==='deck'&&k?button('hold',s.hold?T('已保留','Held'):T('保留至下回合 · 1 金币','Hold until next round · 1 gold'),'text-button',s.hold||pl.gold<1?'disabled':''):''}</div>`;}).join('')}</div><div class="shop-footer">${button('toggle-shop',T('查看游戏板','View board'),'secondary')}<span>${T('商品进入手牌，下一回合可装备给英雄。','Purchases go to your hand and can be equipped to heroes next round.')}</span>${button('finish-shop',`${T('完成购物','Done shopping')} ${icon('arrow')}`,'primary')}</div></section></div>`;}
function getDeploymentPlan(){if(!deploymentPlan||deploymentPlan.game!==game||deploymentPlan.round!==game.s.round){deploymentPlan=new ArtifactBoard.DeploymentPlan(game);deploymentPlan.round=game.s.round;}return deploymentPlan;}
function deploymentEquipmentHTML(u){return `<div class="deployment-equipment" aria-label="${T('英雄装备','Hero equipment')}">${['Weapon','Armor','Accessory'].map(slot=>{const item=C[u.items?.[slot]?.k],label=slot==='Weapon'?T('武器','Weapon'):slot==='Armor'?T('护甲','Armor'):T('饰品','Accessory');return `<span class="${item?'equipped':''}" ${item?`data-card="${item.key}"`:''} data-equipment-slot="${slot}" tabindex="0" aria-label="${esc(label+'：'+(item?cardName(item):T('未装备','Empty')))}">${item?`<img src="${item.art}" alt="${esc(cardName(item))}">`:icon(slot==='Weapon'?'sword':slot==='Armor'?'shield':'heart')}</span>`;}).join('')}</div>`;}
function deployPreviewHTML(u,l){const card=C[u.k];return `<button class="deploy-preview ${card.color.toLowerCase()} ${ui.deploySelected===u.uid?'selected':''}" data-card="${u.k}" data-action="select-deploy" data-id="${u.uid}" data-deploy-hero="${u.uid}" draggable="true" aria-label="${T('调整','Reposition ')}${esc(cardName(card))}，${T('预分路','planned for ')}${LN(l)}"><img src="${card.art}" alt=""><strong>${esc(cardName(card))}</strong><span>${T('待确认','Pending')}</span>${deploymentEquipmentHTML(u)}</button>`;}
function assignDeployment(id,lane){if(online?.deploymentLocked())return;if(ui.busy||game.s.phase!=='deploy')return;getDeploymentPlan().assign(Number(id),lane);ui.deploySelected=Number(id);write('artifact.match',game.s);sound.play('select');render();}
function deployHTML(){if(online?.isSpectator())return '';const plan=getDeploymentPlan(),ready=plan.ready,assigned=ready.filter(u=>Number.isInteger(plan.lane(u.uid))).length;return `<section class="deployment-tray" aria-label="${T('英雄分路规划','Hero lane planning')}"><div class="deployment-heading"><div><small>${T('第 '+game.s.round+' 回合','Round '+game.s.round)} · ${T('部署','Deployment')}</small><h2>${T('英雄重返战场','Heroes return to battle')}</h2></div><p>${T('观察三路局势，拖动英雄预分路。确认前可反复调整。','Survey the lanes and drag heroes to pre-assign them. You can adjust freely before confirming.')}</p><div class="deployment-progress" role="status">${T('已安排','Assigned')} ${assigned} / ${ready.length}</div>${button('reset-deploy',T('重置安排','Reset plan'),'text-button',assigned?'':'disabled')}${button('finish-deploy',online?.deploymentLocked()?T('分路已确认 · 等待对方','Lanes locked · waiting for opponent'):ready.length?T('确认分路 · 进入上路','Confirm lanes · to Top Lane'):T('进入上路','Enter Top Lane'),'primary',plan.complete&&!online?.deploymentLocked()?'':'disabled')}</div><div class="deployment-content"><div class="deployment-heroes">${ready.length?ready.map(u=>`<article class="deployment-hero ${C[u.k].color.toLowerCase()} ${ui.deploySelected===u.uid?'selected':''} ${Number.isInteger(plan.lane(u.uid))?'assigned':''}" data-card="${u.k}" data-deploy-hero="${u.uid}" draggable="true"><button data-action="select-deploy" data-id="${u.uid}" aria-pressed="${ui.deploySelected===u.uid}" aria-label="${T('选择','Select ')}${esc(cardName(C[u.k]))}${T('部署',' for deployment')}"><img src="${C[u.k].art}" alt=""><span><strong>${esc(cardName(C[u.k]))}</strong><small>${CN(C[u.k].color)} · ${game.stats(u).attack} ${T('攻','ATK')} / ${game.stats(u).armor} ${T('甲','ARM')} / ${game.stats(u).health} ${T('血','HP')}</small><b>${Number.isInteger(plan.lane(u.uid))?T('预分路 · ','Assigned · ')+LN(plan.lane(u.uid)):T('等待分路','Unassigned')}</b></span></button>${deploymentEquipmentHTML(u)}</article>`).join(''):`<p class="no-returning-heroes">${T('本回合没有待回归英雄，可以直接进入上路。','No heroes are returning this round — you can head straight to Top Lane.')}</p>`}</div>${ui.deploySelected?`<div class="deployment-controls"><strong>${esc(cardName(C[game.get(ui.deploySelected).k]))}</strong><div>${[0,1,2].map(l=>button('assign-deploy',LN(l),plan.lane(ui.deploySelected)===l?'secondary selected':'secondary',`data-lane="${l}"`)).join('')}${button('unassign-deploy',T('撤回','Recall'),'text-button',Number.isInteger(plan.lane(ui.deploySelected))?'':'disabled')}</div><small>${T('也可直接拖到棋盘，落位在确认时决定。','You can also drag heroes onto the board; placement is decided on confirm.')}</small></div>`:`<div class="deployment-controls"><strong>${T('先选择一位英雄','Select a hero first')}</strong><small>${T('点击英雄再选择线路，或将英雄拖到任意战线。','Click a hero, then pick a lane — or drag the hero onto any lane.')}</small></div>`}</div></section>`;}
function layoutBoard(){const screen=$('.battle-screen');if(!screen)return;const pass=$('.pass-area');if(pass&&pass.parentElement!==screen)screen.appendChild(pass);const r=screen.getBoundingClientRect(),g=ArtifactBoard.layout(r.width,r.height,ui.focus,game.s.phase==='deploy',game.s.phase==='deploy'?($('.deployment-tray')?.getBoundingClientRect().height||0)+24:0,game.s.activeLanes||3);if(matchMedia('(orientation:landscape) and (max-width:1024px) and (max-height:540px)').matches)g.unitHeight=Math.max(g.unitHeight,Math.min(70,g.height*.27));for(const [k,v] of Object.entries({x:g.x,y:g.y,w:g.width,h:g.height,'portal-x':g.portalX,'portal-y':g.portalY,'portal-size':g.portalSize,'unit-h':g.unitHeight}))screen.style.setProperty('--scene-'+k,v+'px');}

function endHTML(){if(online)return online.endHTML(game);if(bridge)return bridge.endHTML(game);const win=game.s.winner===0,tie=game.s.winner===2;return `<div class="phase-overlay"><section class="end-panel"><div class="victory-glyph">${icon(win?'shield':'sword')}</div><div class="eyebrow">${tie?'DRAW':win?'RADIANT VICTORY':'DIRE VICTORY'}</div><h2>${tie?T('平局','Draw'):win?T('天辉胜利','Radiant Victory'):T('夜魇胜利','Dire Victory')}</h2><p>${T('第 '+game.s.round+' 回合','Round '+game.s.round)} · ${LN(game.s.lane)}${T('决胜',' decider')}</p><div class="end-towers">${[0,1,2].map(l=>`<span>${LN(l)}<strong>${game.s.lanes[l].towers[1].fallen?T('敌塔已破','Tower destroyed'):T('敌塔 ','Enemy tower ')+game.s.lanes[l].towers[1].hp}</strong></span>`).join('')}</div><div class="lobby-actions">${button('start',T('再来一局','Play again'),'primary')}${button('copy-opponent-deck',T('保存对手构筑','Save opponent deck'),'secondary')}${button('log',T('查看战斗记录','View battle log'),'secondary')}${button('lobby',T('返回主菜单','Main menu'),'text-button')}</div></section></div>`;}
function inspectorHTML(){const u=game.get(ui.inspect);if(!u)return '';const c=C[u.k],st=game.stats(u),a=game.abilities(u);return `<aside class="inspector ${ui.inspectSkill?'skill-focused':''}"><div class="inspector-top"><span>${T('单位详情','Unit details')}</span>${button('close-inspector',icon('close'),'icon-button',`aria-label="${T('关闭','Close')}"`)}</div><img class="inspector-art" src="${c.art}" alt="${cardName(c)}"><div class="inspector-content"><small class="color-${c.color.toLowerCase()}">${CN(c.color)} · ${TN(c.type)}</small><h2>${cardName(c)}</h2><span class="english-name">${T(c.en||'',c.name)}</span><div class="inspector-stats">${icon('sword')}${st.attack} ${icon('shield')}${st.armor} ${icon('heart')}${st.hp}/${st.health}</div>${heroSkills(u).length?heroSkillDetails(u):`<p>${esc(cardText(c)||T('无额外技能。','No additional abilities.'))}</p>`}${a.filter(v=>!heroSkills(u).some(s=>(s.k||u.k)===v.k)).map(v=>button('activate',`${icon('bolt')} ${esc(T(v.name,C[v.k]?.en||v.name))} <small>${v.remaining?T('冷却 ','Cooldown ')+v.remaining:T('使用技能','Use ability')}</small>`,'ability-button',`data-id="${u.uid}" data-key="${v.k}" ${u.owner!==0||!u.alive||u.lane!==game.s.lane||v.remaining||!game.enabled(u)||game.s.turn!==0||game.s.phase!=='action'?'disabled':''}`)).join('')}${u.hero?`<h3>${T('装备','Equipment')}</h3><div class="inspector-items">${['Weapon','Armor','Accessory'].map(slot=>`<div>${icon(slot==='Weapon'?'sword':slot==='Armor'?'shield':'mana')}<span>${u.items[slot]?cardName(C[u.items[slot].k]):({Weapon:T('空武器','No weapon'),Armor:T('空护甲','No armor'),Accessory:T('空饰品','No accessory')}[slot])}</span></div>`).join('')}</div>`:''}${u.mods.length?`<h3>${T('状态与修改','Status & modifiers')}</h3><div class="mod-list">${u.mods.map(m=>`<span>${modText(m)}</span>`).join('')}</div>`:''}</div></aside>`;}
function modText(m){const names={attack:T('攻击','Attack'),armor:T('护甲','Armor'),health:T('生命','Health'),cleave:T('溅射','Cleave'),retaliate:T('反伤','Retaliate'),siege:T('攻城','Siege'),regen:T('恢复','Regeneration'),shield:T('护盾','Shield'),root:T('缠绕','Root'),flipped:T('恐惧翻牌','Feared'),shadowRealm:T('暗影之境','Shadow Realm'),shadowBonus:T('下次攻击额外伤害','Bonus next attack'),stun:T('眩晕','Stun'),silence:T('沉默','Silence'),disarm:T('缴械','Disarm'),immune:T('伤害免疫','Damage immunity'),deathShield:T('免死护盾','Death shield'),poison:T('毒性伤害','Poison'),pierce:T('穿刺','Piercing'),bounty:T('赏金','Bounty'),taunt:T('嘲讽','Taunt'),neighborArmor:T('邻位护甲','Neighbor armor'),auraRegen:T('恢复光环','Regeneration aura'),heartstopper:T('竭心光环','Heartstopper aura'),coordinated:T('协同突击','Coordinated assault'),soulSpring:T('春之灵','Soul of Spring'),standards:T('军旗','Standards'),risingAnger:T('怒意','Rising anger'),heroicResolve:T('英雄意志','Heroic resolve'),towerMana:T('防御塔魔力','Tower mana'),cookie:T('饼干标记','Cookie marker')};return esc(Object.keys(m).filter(k=>names[k]).map(k=>`${names[k]}${typeof m[k]==='number'&&!['stun','silence','disarm','immune','poison','taunt'].includes(k)?(m[k]>0?'+':'')+m[k]:''}`).join(' · '))+`<small>${m.until==='round'?T('本回合','This round'):m.until==='combat'?T('下次战斗后结束','Until next combat'):m.until==='death'?T('阵亡前','Until death'):T('持续修改','Persistent')}</small>`;}
function filteredCards(){const f=ui.filter;return CARDS.filter(c=>(f.expansion==='All'||(c.expansion||'classic')===f.expansion)&&(f.type==='All'||c.type===f.type)&&(f.color==='All'||c.color===f.color)&&(!f.q||`${c.name} ${c.en} ${c.aliases||''} ${c.text}`.toLowerCase().includes(f.q.toLowerCase()))).sort((a,b)=>a.mana-b.mana||a.id-b.id);}
function collection(){const isDeck=ui.route==='decks',cs=filteredCards();return `<main class="collection-screen ${isDeck?'with-builder':''}"><div class="collection-main"><div class="collection-heading"><div><div class="eyebrow">${isDeck?'DECK CONSTRUCTION':'THE ARCHIVE'}</div><h1>${isDeck?T('牌组构筑','Deck Builder'):T('卡牌图鉴','Collection')}</h1><p>${isDeck?T('选择五位英雄，构筑你的三路战术。','Pick five heroes and build your three-lane strategy.'):T('Classic 303 条目 + Dota 2 自定义扩展 17 条目 · 53 位英雄','303 Classic cards + 17 custom Dota 2 expansion entries · 53 heroes')}</p></div><span class="collection-count">${cs.length}<small>${T(' 张卡牌',' cards')}</small></span></div><div class="collection-filters"><label class="search-field">${icon('search')}<input id="card-search" type="search" placeholder="${T('搜索名称、英雄或技能…','Search names, heroes or abilities…')}" value="${esc(ui.filter.q)}" aria-label="${T('搜索卡牌','Search cards')}"></label><select id="expansion-filter" aria-label="${T('扩展包','Expansion')}">${[['All',T('全部扩展包','All expansions')],['classic',T('Classic 原版','Classic')],['dota2',T('Dota 2 扩展 · 本次新增','Dota 2 expansion · new')]].map(([k,n])=>`<option value="${k}" ${ui.filter.expansion===k?'selected':''}>${n}</option>`).join('')}</select><select id="type-filter" aria-label="${T('卡牌类型','Card type')}"><option value="All">${T('全部类型','All types')}</option>${Object.entries(typeName).map(([k,n])=>`<option value="${k}" ${ui.filter.type===k?'selected':''}>${n}</option>`).join('')}</select><div class="color-filters">${['All','Red','Green','Blue','Black','Neutral'].map(k=>button('filter-color',k==='All'?T('全部','All'):`<span class="color-diamond ${k.toLowerCase()}"></span>`,ui.filter.color===k?'color-filter active':'color-filter',`data-color="${k}" title="${CN(k)||T('全部颜色','All colors')}" aria-label="${CN(k)||T('全部颜色','All colors')}"`)).join('')}</div></div><div class="catalog-grid">${cs.map(c=>`<div class="catalog-item">${button('card-info',cardHTML(c.key), 'catalog-card-button',`data-key="${c.key}" aria-label="${T('查看','Inspect ')}${cardName(c)}"`)}${isDeck?button('deck-add',deckAddLabel(c),'deck-add',`data-key="${c.key}" ${c.token||c.signatureOf?'disabled':''}`):`<span class="catalog-meta">${c.token?T('衍生单位','Token'):c.signatureOf?T('英雄专属','Signature'):T(({Basic:'基础',Common:'普通',Uncommon:'非凡',Rare:'稀有'}[c.rarity]),c.rarity)}</span>${audioButton(c.key)}`}</div>`).join('')||`<div class="empty-results">${T('没有找到匹配的卡牌。','No cards match your search.')}</div>`}</div></div>${isDeck?builderHTML():''}</main>`;}
function deckAddLabel(c){if(c.token)return T('衍生单位','Token');if(c.signatureOf)return T('随英雄加入','Joins with hero');const d=ui.builder,n=c.type==='Hero'?d.heroes.includes(c.key)?1:0:[...d.main,...d.items].filter(k=>k===c.key).length;return c.type==='Hero'?(n?T('已选择 · 移除','Selected · remove'):T('+ 选择英雄','+ Choose hero')):`${T('+ 加入牌组','+ Add to deck')}${n?' · '+n+' / 3':''}`;}
function builderHTML(){const d=ui.builder,errs=game.validateDeck(d),sig=d.heroes.flatMap(k=>C[k]?.signature?[C[k].signature,C[k].signature,C[k].signature]:[]),list=[...d.main,...sig],count={};list.forEach(k=>count[k]=(count[k]||0)+1);const items={};d.items.forEach(k=>items[k]=(items[k]||0)+1);const renderList=(v,section)=>Object.entries(v).sort((a,b)=>(C[a[0]]?.mana||0)-(C[b[0]]?.mana||0)).map(([k,n])=>`<div class="deck-row" data-card="${k}"><span class="row-mana ${C[k].color.toLowerCase()}">${section==='items'?C[k].gold:C[k].mana}</span><strong>${esc(cardName(C[k]))}</strong>${C[k].signatureOf?`<small>${T('专属','SIG')}</small>`:button('deck-remove','−','count-button',`data-key="${k}"`)}<b>${n}</b>${!C[k].signatureOf?button('deck-add','+','count-button',`data-key="${k}"`):''}</div>`).join('');

 const curve=Array.from({length:9},(_,i)=>list.filter(k=>Math.min(8,C[k].mana)===i).length),max=Math.max(1,...curve);
 return `<aside class="deck-builder"><div class="builder-heading"><input id="deck-name" aria-label="${T('牌组名称','Deck name')}" value="${esc(pick(d,'name'))}" maxlength="40"><div>${button('deck-load',T('预设','Presets'),'text-button')}${button('deck-clear',T('清空','Clear'),'text-button')}</div></div><div class="builder-heroes">${d.heroes.map((k,i)=>`<div data-card="${k}"><img src="${C[k].art}" alt="${cardName(C[k])}"><span>${i<3?T('首发','Starting'):i===3?T('回合 2','Round 2'):T('回合 3','Round 3')}</span>${button('hero-order','↔','hero-order',`data-index="${i}" title="${T('将此英雄向前调整','Move this hero earlier')}" aria-label="${T('调整','Reorder ')}${cardName(C[k])}${T('部署顺序',' deployment order')}"`)}</div>`).join('')}${Array.from({length:Math.max(0,5-d.heroes.length)},()=>'<div class="empty-hero">+</div>').join('')}</div><div class="mana-curve" aria-label="${T('魔力曲线','Mana curve')}">${curve.map((n,i)=>`<div title="${i} ${T('魔力：','mana: ')}${n} ${T('张','cards')}"><span>${n||''}</span><i style="height:${n/max*44}px"></i><small>${i===8?'8+':i}</small></div>`).join('')}</div><div class="deck-section-heading"><span>${T('主牌组','Main deck')}</span><strong>${list.length} <small>/ ${T('至少 40','min 40')}</small></strong></div><div class="deck-list">${renderList(count,'main')}</div><div class="deck-section-heading"><span>${T('物品牌组','Item deck')}</span><strong>${d.items.length}<small> / ${T('至少 9','min 9')}</small></strong></div><div class="deck-list items-list">${renderList(items,'items')}</div><div class="builder-footer"><div class="deck-validation ${errs.length?'invalid':'valid'}">${errs.length?esc(L(errs[0])):icon('check')+T('牌组可用于对战','Deck is legal for play')}</div><div>${button('deck-import',T('导入','Import'),'secondary')}${button('deck-export',T('导出','Export'),'secondary')}${button('deck-share',T('分享码','Share code'),'secondary',errs.length?'disabled':'')}${button('deck-share-import',T('导入分享码','Import code'),'secondary')}${button('deck-save',T('保存牌组','Save deck'),'primary',errs.length?'disabled':'')}</div></div></aside>`;}
// Full-page renders must not restart the shop entrance on purchases or holds.
function render(){stopAudition();const hadHand=!!$('.hand-scroll'),handScroll=$('.hand-scroll')?.scrollLeft||0,oldHand=new Set([...document.querySelectorAll('[data-hand]')].map(e=>e.dataset.hand)),deals=new Map([...document.querySelectorAll('[data-deal-at]')].map(e=>[e.dataset.hand,{at:Number(e.dataset.dealAt),index:Number(e.dataset.dealIndex)}])),effectLayer=$('#fx-layer'),previousShop=$('.shop-panel,.end-panel'),shopAnimation=previousShop?.getAnimations()[0],shopTime=shopAnimation?.currentTime,shopFinished=!shopAnimation||shopAnimation.playState==='finished';sound.setScene(ui.route!=='battle'?'menu':ui.intro?'intro':game.s.phase==='ended'?(game.s.winner===2?'draw':game.s.winner===0?'victory':'defeat'):game.s.phase==='shop'?'shop':'battle');document.body.classList.toggle('in-battle',ui.route==='battle');document.body.classList.toggle('spectator',!!online?.isSpectator());const scroll=ui.route==='collection'||ui.route==='decks'?window.scrollY:0;if(effectLayer&&effectLayer.parentElement!==document.body)document.body.appendChild(effectLayer);$('#app').innerHTML=header()+(ui.route==='lobby'?lobby():ui.route==='battle'?battle():collection())+`<div id="toast" class="toast" role="status" aria-live="polite"></div><div id="card-tooltip" class="card-tooltip" role="tooltip"></div><dialog id="modal"></dialog>`;const newLayer=$('#app #fx-layer');if(effectLayer&&newLayer)newLayer.remove();else if(newLayer)document.body.appendChild(newLayer);if(ui.route!=='battle')effectLayer?.remove();if(scroll)window.scrollTo(0,scroll);layoutBoard();const shop=$('.shop-panel,.end-panel');if(previousShop&&shop){const animation=shop.getAnimations()[0];if(animation&&shopTime!=null&&!shopFinished)animation.currentTime=shopTime;else shop.style.animation='none';}const hand=$('.hand-scroll');if(hand){hand.scrollLeft=handScroll;if(hadHand){const fresh=[...hand.querySelectorAll('[data-hand]')].filter(e=>!oldHand.has(e.dataset.hand));if(fresh.length){sound.play('draw');for(const [i,card] of fresh.entries())deals.set(card.dataset.hand,{at:Date.now(),index:i});hand.scrollLeft=hand.scrollWidth;}}for(const card of hand.querySelectorAll('[data-hand]')){const deal=deals.get(card.dataset.hand);if(deal&&Date.now()-deal.at<560+deal.index*110){card.dataset.dealAt=deal.at;card.dataset.dealIndex=deal.index;ArtifactScene.deal(card,deal.index,Date.now()-deal.at);}}}
 const host=$('.header-tools');if(host)I18N&&I18N.mountSwitcher&&I18N.mountSwitcher(host);}
function toast(s){s=L(s);if($('#modal')?.open){let err=$('#modal .dialog-feedback');if(!err){err=document.createElement('p');err.className='dialog-feedback';$('#modal').appendChild(err);}err.textContent=s;}const el=$('#toast');el.textContent=s;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el?.classList.remove('visible'),3200);}
function modal(content,wide=false){modalReturn=document.activeElement;stopAudition();const el=$('#modal');el.className=wide?'wide':'';el.innerHTML=`<div class="modal-close">${button('close-modal',icon('close'),'icon-button',`aria-label="${T('关闭','Close')}"`)}</div>${content}`;el.showModal();el.addEventListener('close',stopAudition,{once:true});el.addEventListener('click',e=>{if(e.target===el)el.close();},{once:true});}
function closeModal(){stopAudition();$('#modal')?.close();modalReturn?.focus?.();}
function audioTracks(k){
 const map=window.ARTIFACT_ACTION_AUDIO,tracks=[],seen=new Set();if(!map)return tracks;
 T('武器装备','Weapon equipment');T('护甲装备','Armor equipment');T('饰品装备','Accessory equipment');
 function add(entry,prefix){for(const [field,label] of [['effect',T('效果音','Sound effect')],['voice',T('英雄语音','Hero voice')]]){const id=entry?.[field];if(id&&!seen.has(id)){seen.add(id);tracks.push({id,label:L(entry.label||prefix)+' · '+label,url:'assets/sfx/'+map.samples[id]});}}}
 add(map.heroes?.[k],T('登场语音','Deploy voice'));add(map.cards[k],C[k].type==='Item'?T('使用 / 装备','Use / equip'):T('打出卡牌','Card played'));add(map.abilities[k],C[k].abilities?.[0]?T(C[k].abilities[0].name,C[k].abilities[0].en||C[k].en||C[k].abilities[0].name):T('主动技能','Active ability'));
 for(const a of C[k].abilities||[])if(a.key&&a.key!==k)add(map.abilities[a.key],T(a.name,a.en||a.name));
 if(C[k].signature)add(map.cards[C[k].signature],T('专属牌 ','Signature card ')+cardName(C[C[k].signature]));
 return tracks;
}
function audioButton(k){const tracks=audioTracks(k);return tracks.length?button('card-audio',T('♫ 试听音频 · ','♫ Listen · ')+tracks.length,'audio-preview-button',`data-key="${k}" aria-label="${T('试听','Listen to ')}${esc(cardName(C[k]))}${T('音频',' audio')}"`):'';}
function stopAudition(){document.querySelectorAll('.audio-audition').forEach(a=>a.pause());sound.previewing=false;sound.setVolumes();}
function showAudio(k){
 stopAudition();const tracks=audioTracks(k);modal(`<div class="audio-gallery"><div class="eyebrow">ARTIFACT AUDIO</div><h2>${esc(cardName(C[k]))} · ${T('音频鉴赏','Audio Gallery')}</h2><p>${T('选择一段播放，可暂停、拖动进度或调节音量。试听时背景音乐暂时降低。','Pick a track — you can pause, scrub or adjust volume. Background music dips while auditioning.')}</p><div class="audio-track-list">${tracks.map(t=>`<section class="audio-track"><h3>${esc(t.label)}</h3><audio class="audio-audition" controls preload="none" aria-label="${esc(t.label)}" src="${t.url}"></audio></section>`).join('')||`<p>${T('尚未找到明确对应的专属音频。','No dedicated audio found for this card yet.')}</p>`}</div></div>`,true);
 document.querySelectorAll('.audio-audition').forEach(a=>a.volume=settings.effects??.6);
}
function showCard(k){const c=C[k];modal(`<div class="card-detail">${cardHTML(k)}<div><div class="eyebrow">${TN(c.type)} · ${CN(c.color)}</div><h2>${cardName(c)}</h2><p class="english-name">${T(c.en||'',c.name)}</p><p class="detail-rules">${esc(cardText(c)||T('无额外技能。','No additional abilities.'))}</p><p class="rules-english">${esc(T(c.textEn||'',c.text||''))}</p>${c.signature?`<div class="signature-info">${T('专属牌 ','Signature: ')}${button('card-info',cardName(C[c.signature]),'text-button',`data-key="${c.signature}"`)} × 3</div>`:''}${c.signatureOf?`<div class="signature-info">${cardName(C[c.signatureOf])}${T('的专属卡牌','\'s signature card')}</div>`:''}${audioButton(k)}<small class="art-credit">ART BY ${esc(c.artist||'Valve')} · CARD ${c.id}</small></div></div>`,true);}
function boardTransition(focus){if(focus!==null&&(focus<0||focus>=(game.s?.activeLanes||3)))return;
 const before=new Map([...document.querySelectorAll('.board>.lane')].map(el=>[el.dataset.lane,el.getBoundingClientRect()]));
 ui.focus=focus;render();
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 document.querySelectorAll('.board>.lane').forEach(el=>{const old=before.get(el.dataset.lane),r=el.getBoundingClientRect();if(!old||!r.width)return;
  el.animate([{transform:`translate(${old.left-r.left}px,${old.top-r.top}px) scale(${old.width/r.width},${old.height/r.height})`},{transform:'none'}],{duration:560/settings.speed,easing:'cubic-bezier(.22,.8,.24,1)'});
 });
}
function commit(){
 if(online?.flush())return;
 const ev=game.s.events.slice();game.s.events=[];
 write('artifact.match',game.s);ui.selection=null;ui.inspect=null;
 const combat=ev.find(e=>e.type==='combat'),cast=ev.find(e=>e.type==='card'||e.type==='ability');
 if(cast){$('.selection-banner')?.remove();sound.prepareAction(cast.card,cast.type);$('.inspector')?.remove();document.querySelectorAll('.targetable,.lane-target').forEach(el=>el.classList.remove('targetable','lane-target'));ui.lastCast=cast;if(cast.owner===1)ui.lastEnemyCast=cast;const affected=[...(cast.targets||[]),...(cast.outcomes||[])];if(ui.focus!==null&&affected.some(t=>t.lane>=0&&t.lane!==ui.focus)){ui.focus=null;$('.battle-screen')?.classList.remove('lane-focused');$('.board')?.classList.remove('focused-board');document.querySelectorAll('.board>.lane').forEach(el=>{el.inert=false;el.removeAttribute('aria-hidden');});document.querySelectorAll('.camera-prev,.camera-next').forEach(el=>el.hidden=true);if($('.camera-label'))$('.camera-label').textContent=T('三路施法','Cross-lane cast');layoutBoard();}}
 if(cast&&!combat&&ui.route==='battle'&&$('.board')){
  ui.busy=true;clearTimeout(aiTimer);
  const immediate=['Creep','Item','Improvement'].includes(C[cast.card]?.type)||bridge&&['summon','equip'].includes(C[cast.card]?.fx);
  if(immediate)render();else if($('#pass-button'))$('#pass-button').disabled=true;
  ArtifactScene.cast($('#fx-layer'),cast,C[cast.card],esc);sound.duck();if(cast.type==='card')sound.play('card');else if(!sound.hasAction(cast.card,cast.type))sound.play('ability');
  const rolling=ev.some(e=>e.type==='rolling');
  const impact=()=>{if(ui.route!=='battle')return;if(rolling){window.ArtifactExpansionFX?.(ev.filter(e=>e.type==='rolling'),$('#fx-layer'),game);setTimeout(()=>{if(ui.route==='battle')playEvents(ev.filter(e=>e.type!=='rolling'));},1900);}else{playEvents(ev);if(!immediate)render();}};
  if(immediate)impact();else fxTimer=setTimeout(impact,180);
  setTimeout(()=>{ui.busy=false;if(ui.route==='battle'){render();scheduleAI();}},ev.some(e=>e.type==='rolling')?2300:ev.some(e=>['shield-crash','cookie','shredder','mortimer-spit','cookie-toss'].includes(e.type))?1100:cast.owner?1000:360);return;
 }
 if(ui.route==='battle'&&combat&&$('.board')){
  ui.busy=true;clearTimeout(aiTimer);clearTimeout(fxTimer);if($('#pass-button'))$('#pass-button').disabled=true;
  const status=$('.turn-status>span:last-child');if(status)status.innerHTML=T('战斗结算中…','Resolving combat…')+'<small>'+T('双方单位同时攻击','All units strike at once')+'</small>';
  if(ui.focus!==null&&ui.focus!==combat.lane){ui.focus=combat.lane;$('.board').style.setProperty('--focus',combat.lane);document.querySelectorAll('.board>.lane').forEach(el=>{el.inert=Number(el.dataset.lane)!==combat.lane;el.setAttribute('aria-hidden',String(el.inert));});}
  if(cast){ArtifactScene.cast($('#fx-layer'),cast,C[cast.card],esc);sound.duck();}
  const deferredPassives=ui.focus!==null?ev.filter(e=>e.type==='passive'&&e.lane!==combat.lane):[];
  animateCombat(combat);
  fxTimer=setTimeout(()=>{
   if(ui.route!=='battle')return;
   playEvents(ev);
   for(const attack of combat.attacks||[]){const el=document.querySelector(`[data-attacker="${attack.unit}"]`);if(el){const r=el.getBoundingClientRect();ArtifactScene.burst($('#fx-layer'),r.left+r.width/2,r.top+r.height/2,attack.target?'hit':'tower');}}
   if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelector(`.lane[data-lane="${combat.lane}"]`)?.animate([{translate:'0 0'},{translate:'4px 2px'},{translate:'-3px -1px'},{translate:'0 0'}],{duration:260/settings.speed});
   // The old board stays visible through impact, including units that died.
   for(const e of ev.filter(e=>e.type==='damage'||e.type==='heal')){
    const el=document.querySelector(`[data-unit="${e.unit}"] .health`);if(el){const u=game.get(e.unit);el.innerHTML=icon('heart')+(u?.alive?game.stats(u).hp:0);const ghost=document.querySelector(`[data-attacker="${e.unit}"] .health`);if(ghost)ghost.innerHTML=el.innerHTML;}
   }
   for(const e of ev.filter(e=>e.type==='tower')){const bar=document.querySelector(`.lane[data-lane="${e.lane}"] .tower-bar.${e.owner?'dire':'radiant'}`),t=game.s.lanes[e.lane].towers[e.owner];if(bar){bar.querySelector('.tower-title strong').innerHTML=Math.max(0,t.hp)+`<small> / ${t.max}</small>`;bar.querySelector('.hp-track>span').style.width=Math.max(0,t.hp/t.max*100)+'%';}}
   fxTimer=setTimeout(()=>{
    if(ui.route!=='battle')return;
    boardTransition(ui.focus===null?null:game.s.lane);
    fxTimer=setTimeout(()=>{ui.busy=false;if(ui.route==='battle'){render();const layer=$('#fx-layer');if(layer&&deferredPassives.length)playPassiveEvents(deferredPassives,layer);scheduleAI();}},580/settings.speed);
   },720/settings.speed);
  },460/settings.speed);
 }else{if(ev.some(e=>e.type==='lane')&&ui.focus!==null)boardTransition(game.s.lane);else render();playEvents(ev);scheduleAI();}
}
function animateCombat(event){
 sound.play('swing');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 for(const attack of event.attacks||[]){
  const unit=document.querySelector(`[data-unit="${attack.unit}"]`);
  const target=attack.target?document.querySelector(`[data-unit="${attack.target}"]`):document.querySelector(`.lane[data-lane="${event.lane}"] .tower-bar.${attack.owner?'radiant':'dire'}`);
  if(!unit||!target)continue;
  const r=unit.getBoundingClientRect(),t=target.getBoundingClientRect();
  const dx=(t.left+t.width/2-r.left-r.width/2)*(attack.target ? .5 : .8),dy=(t.top+t.height/2-r.top-r.height/2)*(attack.target ? .5 : .72);
  const ghost=unit.cloneNode(true);ghost.removeAttribute('data-unit');ghost.dataset.attacker=attack.unit;ghost.inert=true;ghost.classList.add('combat-ghost');ghost.querySelector('.game-card').style.height=unit.querySelector('.game-card').getBoundingClientRect().height+'px';ghost.querySelector('.card-copy strong').style.fontSize=getComputedStyle(unit.querySelector('.card-copy strong')).fontSize;Object.assign(ghost.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',margin:'0',zIndex:'12'});$('#fx-layer').appendChild(ghost);unit.style.visibility='hidden';
  ghost.style.setProperty('--unit-height',unit.querySelector('.game-card').getBoundingClientRect().height+'px');
  const animation=ghost.animate(reduced?[{opacity:1},{opacity:.65},{opacity:1}]:[
   {transform:'translate(0,0) scale(1)',offset:0},
   {transform:`translate(0,${attack.owner?-12:12}px) scale(1.16) rotate(${attack.owner?-4:4}deg)`,filter:'drop-shadow(0 14px 12px #000b)',offset:.28},
   {transform:`translate(${dx}px,${dy}px) scale(1.1) rotate(${attack.owner?3:-3}deg)`,filter:'brightness(1.5) drop-shadow(0 0 12px #ebc578)',offset:.56},
   {transform:`translate(${dx*.85}px,${dy*.85}px) scale(1.04)`,offset:.66},
   {transform:'translate(0,0) scale(1)',offset:1}
  ],{duration:820/settings.speed,easing:'cubic-bezier(.3,.05,.3,1)'});
  animation.onfinish=()=>{unit.style.visibility='';ghost.remove();};
 }
}
function playPassiveEvents(events,layer){for(const e of events.filter(e=>e.type==='passive')){const source=document.querySelector(`[data-unit="${e.unit}"]`),target=document.querySelector(`[data-unit="${e.target}"]`);if(!source||source.closest('[inert]'))continue;const badge=source.querySelector('.hero-skill-icon.passive')||source;badge.animate([{filter:'brightness(1)'},{filter:'brightness(2.2)',boxShadow:'0 0 18px #adccff'},{filter:'brightness(1)'}],{duration:950});const r=source.getBoundingClientRect(),label=document.createElement('span');label.className='passive-skill-float';label.textContent=L(e.skill)+' · '+T('自动触发','auto')+(e.target&&game.get(e.target)?' → '+cardName(C[game.get(e.target).k]):'');label.style.left=r.left+r.width/2+'px';label.style.top=r.top-12+'px';layer.appendChild(label);setTimeout(()=>label.remove(),2200);if(target&&!target.closest('[inert]')){const t=target.getBoundingClientRect(),ring=document.createElement('span');ring.className='passive-target-ring '+(e.card==='luna'?'moonlight':e.card==='zeus'?'static-field':'passive-buff');ring.style.left=t.left+t.width/2+'px';ring.style.top=t.top+t.height/2+'px';layer.appendChild(ring);setTimeout(()=>ring.remove(),1000);}const status=$('#cast-status');if(status)status.textContent=label.textContent;}}
function playEvents(events){
 if(!events?.length)return;const fallen=events.filter(e=>e.type==='destroy'&&Number.isInteger(e.lane));if(fallen.length){for(const owner of new Set(fallen.map(e=>e.owner)))sound.play(owner?'event-tower-fall-dire':'event-tower-fall-radiant');}else if(events.some(e=>e.type==='tower'&&e.amount>0))sound.play('event-tower-hit');if(events.some(e=>e.type==='mine')){sound.play('mine');sound.play('voice-mine');}if(events.some(e=>e.type==='death'&&game.get(e.unit)?.hero))sound.play('event-hero-death');if(events.some(e=>e.type==='return'))sound.play('event-hero-return');for(const e of events.filter(e=>e.type==='summon')){const unit=document.querySelector(`[data-unit="${e.unit}"]`),summoned=game.get(e.unit);if(unit&&!unit.closest('[inert]'))ArtifactScene.summon(unit,summoned?.owner||0);const heroVoice=summoned?.hero&&(window.ARTIFACT_ACTION_AUDIO?.heroes||{})[summoned.k];if(heroVoice?.voice)sound.play(heroVoice.voice);}
 const types=events.map(e=>e.type),priority=['victory','combat','destroy','ability','buy','card','heal','death','round','lane','pass','summon'];const typ=priority.find(t=>types.includes(t));if(typ&&typ!=='victory'&&!(typ==='destroy'&&fallen.length)&&!events.some(e=>e.type==='card'||e.type==='ability'))sound.play(typ);const layer=$('#fx-layer');if(!layer)return;playPassiveEvents(events,layer);window.ArtifactExpansionFX?.(events,layer,game);window.ArtifactElementalFX?.(events,layer,game);
 events.filter(e=>e.type==='damage'||e.type==='heal'||e.type==='tower').forEach(e=>{const u=e.type==='tower'?document.querySelector(`.lane[data-lane="${e.lane}"] .tower-bar.${e.owner?'dire':'radiant'}`):document.querySelector(`[data-attacker="${e.unit}"]`)||document.querySelector(`[data-unit="${e.unit}"]`);if(u){u.classList.add(e.type==='heal'?'heal-glow':'impact');const r=u.getBoundingClientRect(),d=document.createElement('span');d.className='damage-float '+(e.type==='heal'?'healing':'');d.textContent=(e.type==='heal'?'+':'−')+e.amount;d.style.left=r.left+r.width/2+'px';d.style.top=r.top+35+'px';layer.appendChild(d);setTimeout(()=>d.remove(),1100);}});
 for(const e of events.filter(e=>e.type==='death'))document.querySelector(`[data-unit="${e.unit}"]`)?.classList.add('unit-fallen');
 const cast=events.find(e=>e.type==='card'||e.type==='ability');if(cast&&C[cast.card]){const c=C[cast.card];if(!layer.querySelector('.skill-reveal'))ArtifactScene.cast(layer,cast,c,esc);ArtifactScene.resolve(layer,cast,c);const text=(cast.outcomes||[]).flatMap(o=>o.changes).join(' '),kind=/伤害/.test(text)?'damage':/回复/.test(text)?'heal':/转为|沉默|眩晕|缴械/.test(text)?'control':/装备/.test(text)?'equip':/进入战场/.test(text)?'summon':'buff';sound.spell(kind,c.color,cast.skill||c.key,cast.type);}

}
function scheduleAI(){clearTimeout(aiTimer);if(bridge||online)return;if(ui.route!=='battle'||ui.intro||game.s?.phase!=='action'||game.s.turn!==1||ui.busy)return;aiTimer=setTimeout(()=>{if(ui.route!=='battle'||game.s.phase!=='action'||game.s.turn!==1)return;if($('#modal')?.open){scheduleAI();return;}try{game.aiStep(1);commit();}catch(e){console.error(e);toast(T('对手行动失败，已让过','Opponent action failed — passed'));game.pass(1);commit();}},850/settings.speed);}
function start(){const d=chosen(ui.deckId),e=chosen(ui.opponentId);game=new Game(CARDS);game.newGame(d,e,Date.now());ui.route='battle';ui.selection=null;ui.focus=0;ui.inspect=null;ui.busy=false;ui.shopHidden=false;ui.intro=true;ui.lastCast=null;ui.lastEnemyCast=null;deploymentPlan=null;ui.deploySelected=null;sound.start().catch(()=>{});commit();}
function chooseAction(kind,id,k){if(ui.busy||online?.isSpectator())return;try{if(kind==='play'){const h=game.s.players[0].hand.find(h=>h.uid===Number(id)),why=game.canPlay(0,h);if(why)throw Error(why);}const source=kind==='ability'?game.get(Number(id))||game.imps(0,game.s.lane).find(i=>i.uid===Number(id)):null;const spec=game.targets(k,0,source);if(!spec.length){if(kind==='play')game.play(0,Number(id),[]);else game.activate(0,Number(id),k,[]);commit();return;}
 ui.selection={kind,id:Number(id),k,spec,targets:[]};ui.inspect=null;if(spec.some(s=>s.cross||s.kind==='lane'))ui.focus=null;sound.play('select');render();
 }catch(e){toast(e.message);sound.play('error');}}
function selectTarget(t){const se=ui.selection;if(!se)return;se.targets.push(t);if(se.targets.length===se.spec.length){try{if(se.kind==='play')game.play(0,se.id,se.targets);else game.activate(0,se.id,se.k,se.targets);commit();}catch(e){se.targets=[];render();toast(e.message);sound.play('error');}}else{render();sound.play('select');}}
// Touch drag selects without spending the card; the same targeting checks apply on release.
function beginHandDrag(id){if(ui.route!=='battle'||ui.intro||ui.busy||online?.isSpectator())return false;const h=game.s.players[0].hand.find(h=>h.uid===Number(id));if(!h)return false;const why=game.canPlay(0,h);if(why){toast(why);return false;}const spec=game.targets(h.k,0);ui.selection={kind:'play',id:h.uid,k:h.k,spec,targets:[]};ui.inspect=null;if(spec.some(s=>s.cross||s.kind==='lane'))ui.focus=null;render();return true;}
function cancelHandDrag(){if(ui.selection?.kind==='play'){ui.selection=null;render();}}
function dropHandAt(x,y){const se=ui.selection;if(!se||se.kind!=='play'||ui.busy||online?.isSpectator()){cancelHandDrag();return false;}const el=document.elementFromPoint(x,y);if(!el||el.closest('[inert],.phase-overlay,.hand-zone,.touch-card-preview')){cancelHandDrag();return false;}const spec=se.spec[se.targets.length],lane=el.closest('.lane'),unit=el.closest('[data-unit]'),slot=el.closest('[data-slot]'),imp=el.closest('.improvement');let target;
 if(!spec){if(lane&&Number(lane.dataset.lane)===game.s.lane){try{game.play(0,se.id,[]);commit();return true;}catch(e){cancelHandDrag();toast(e.message);return false;}}}
 else if(spec.kind==='unit'&&unit&&validUnit(game.get(unit.dataset.unit)))target=Number(unit.dataset.unit);
 else if(spec.kind==='position'&&slot&&slot.dataset.owner==='0'&&(spec.cross||Number(slot.dataset.lane)===game.s.lane)&&game.positionTargets(0,Number(slot.dataset.lane),spec).includes(Number(slot.dataset.slot)))target={lane:Number(slot.dataset.lane),pos:Number(slot.dataset.slot)};
 else if(spec.kind==='lane'&&lane)target=Number(lane.dataset.lane);
 else if(spec.kind==='improvement'&&imp&&(spec.cross||Number(imp.dataset.lane)===game.s.lane)&&(!spec.enemy||imp.dataset.owner==='1'))target=Number(imp.dataset.id);
 if(target!==undefined){selectTarget(target);return true;}cancelHandDrag();return false;
}
function addDeck(k,remove=false){const c=C[k],d=ui.builder;if(c.type==='Hero'){if(d.heroes.includes(k)){d.heroes=d.heroes.filter(h=>h!==k);}else if(d.heroes.length<5)d.heroes.push(k);else return toast(T('最多选择 5 位英雄，先移除一位再添加','Pick at most 5 heroes — remove one first'));}else{if(c.signatureOf||c.token)return;const list=c.type==='Item'?d.items:d.main;if(c.type==='Item'&&c.itemType==='Consumable')return toast(T('消耗品由商店随机提供，不加入物品牌组','Consumables come from the shop and are not added to the item deck'));const n=list.filter(x=>x===k).length;if(remove){const i=list.indexOf(k);if(i>=0)list.splice(i,1);}else if(n>=3)return toast(T('同名卡牌最多 3 张','At most 3 copies of a card'));else list.push(k);}render();sound.play('select');}
function saveFile(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function help(){modal(`<div class="help-content"><div class="eyebrow">HOW TO PLAY</div><h2>${T('三路战场，两个胜利目标','Three lanes, two ways to win')}</h2><p>${T('摧毁对手两座防御塔，或在同一路继续摧毁遗迹，即可获胜。','Destroy two enemy towers — or push on to destroy the ancient in the same lane — to win.')}</p><div class="rule-grid"><div><b>01</b><h3>${T('英雄决定颜色','Heroes grant color')}</h3><p>${T('本路需要一位未被沉默或眩晕的对应颜色英雄，才能施放同色卡牌。物品不消耗魔力。','A lane needs a living, un-silenced, un-stunned hero of the matching color to play that color\'s cards. Items cost no mana.')}</p></div><div><b>02</b><h3>${T('依次推进三路','Lanes resolve in order')}</h3><p>${T('上路 → 中路 → 下路。双方交替行动，连续两次让过后，单位按照箭头同时攻击。','Top → Middle → Bottom. Players alternate actions; after two consecutive passes, units strike along their arrows simultaneously.')}</p></div><div><b>03</b><h3>${T('先手权与魔力','Initiative & mana')}</h3><p>${T('连续让过中的第一位玩家在下一路先行动。每路魔力独立，从 3 开始，每轮增加 1 并恢复。','The first player to pass goes first on the next lane. Mana is per-lane, starts at 3, and grows by 1 each round, fully refreshed.')}</p></div><div><b>04</b><h3>${T('金币、商店与复活','Gold, shop & respawn')}</h3><p>${T('击杀英雄获得 5 金币，小兵获得 1 金币。三路结束后购物；阵亡英雄通常隔一整轮重新部署。','Hero kills grant 5 gold, creep kills 1. Shop after all three lanes; slain heroes usually redeploy after a full round.')}</p></div></div><div class="keyword-list"><span><b>${T('护甲','Armor')}</b> ${T('抵消每次伤害；负护甲使伤害增加','negates each hit; negative armor increases damage')}</span><span><b>${T('穿刺','Piercing')}</b> ${T('忽略护甲','ignores armor')}</span><span><b>${T('溅射','Cleave')}</b> ${T('对目标相邻单位造成伤害','damages units adjacent to the target')}</span><span><b>${T('反伤','Retaliate')}</b> ${T('受到攻击时伤害攻击者','damages attackers when attacked')}</span><span><b>${T('攻城','Siege')}</b> ${T('被阻挡时仍可对塔造成伤害','still damages the tower when blocked')}</span><span><b>${T('免死护盾','Death shield')}</b> ${T('抵挡一次阵亡并保留 1 生命','survives death once at 1 health')}</span></div><p class="keyboard-help">${T('操作：点击或拖动手牌 → 点击亮起的目标；点击英雄使用技能。空格：让过；Esc：取消；1 / 2 / 3：聚焦战线；0：三路总览。','Controls: click or drag a card → click a highlighted target; click a hero to use abilities. Space: pass; Esc: cancel; 1 / 2 / 3: focus a lane; 0: all lanes.')}</p>${button('close-modal',T('返回战场','Back to battle'),'primary')}</div>`,true);}
function about(){modal(`<div class="about-content"><div class="eyebrow">ARTIFACT · THREEFOLD</div><h2>${T('还原范围与资料来源','Scope & sources')}</h2><p>${T('这是以 Artifact Classic 为目标的非官方浏览器重制，可离线与电脑对战。收录 303 个 Classic 条目和 17 个 Dota 2 自定义扩展条目，共 53 位英雄。石鳞剑士、邪影芳灵、齐天大圣、炸弹人与电炎绝手使用官方名称和美术，技能数值与规则为本系统自定义。','An unofficial, offline-capable browser recreation of Artifact Classic. It contains 303 Classic entries and 17 custom Dota 2 expansion entries, with 53 heroes total. Pangolier, Dark Willow, Monkey King, Techies, and Snapfire use official names and art with custom Threefold rules.')}</p><p>${T('三路行动、商店、组牌、装备与卡牌效果已接入。复杂技能的边界交互与原版仍可能存在差异；电脑为本地启发式对手，不包含 Steam 联机、赛事和市场。','Three-lane play, the shop, deck building, equipment, and card effects are implemented. Edge-case interactions may differ from the original; the computer player is a local heuristic opponent. Steam play, tournaments, and the market are not included.')}</p><p>${T('背景配乐使用项目内音轨；扩展英雄包含已记录来源的语音与技能音效，并提供浏览器动画及减少动态效果支持。战斗预测不计入免死护盾后的所有连锁反应。','The project includes background tracks plus source-recorded expansion hero voices and skill effects, browser animations, and reduced-motion support. Combat forecasts do not follow every chain after a death shield.')}</p><ul><li><a href="https://github.com/ValveSoftware/ArtifactDeckCode" target="_blank" rel="noreferrer">Valve · ${T('卡牌接口与牌组结构','card API & deck format')}</a></li><li><a href="https://github.com/Open-Artifact/artifactdb-set-1" target="_blank" rel="noreferrer">Open-Artifact · ${T('Classic 卡牌与卡画存档','Classic card & art archive')}</a></li><li><a href="https://github.com/SteamDatabase/GameTracking-Artifact" target="_blank" rel="noreferrer">${T('客户端中英文文本记录','Client zh/en text records')}</a></li><li><a href="https://www.dota2.com/heroes" target="_blank" rel="noreferrer">Valve · Dota 2</a></li></ul><small>Artifact, Dota ${T('及所有原版卡画与音频','and all original card art and audio')} © Valve Corporation. ${T('画作与音频来源记录在 research 目录；此项目与 Valve 无隶属关系。','Art and audio provenance is recorded under research. This project is not affiliated with Valve.')}</small></div>`,true);}
function showSettings(){modal(`<div class="settings-content"><div class="eyebrow">SETTINGS</div><h2>${T('游戏设置','Settings')}</h2><label>${T('背景音乐','Music')} <input type="range" id="music-volume" min="0" max="1" step=".01" value="${settings.music}"></label><label>${T('音效','Sound effects')} <input type="range" id="effects-volume" min="0" max="1" step=".01" value="${settings.effects}"></label><label>${T('动画与对手速度','Animation & AI pace')}<select id="game-speed"><option value="1" ${settings.speed===1?'selected':''}>${T('沉浸 · 正常速度','Immersive · normal speed')}</option><option value="1.8" ${settings.speed===1.8?'selected':''}>${T('快速 · 1.8 倍','Fast · 1.8×')}</option></select></label><label class="check-setting"><input type="checkbox" id="forecast-setting" ${settings.showForecast?'checked':''}> ${T('显示战斗伤害预测','Show combat damage forecast')}</label><p>${T('原声会随开场、战斗、商店与胜负阶段切换，施法时自动降低配乐音量。声音需要首次点击后启用。存档、牌组和设置保存在当前设备。','Music shifts with intro, combat, shop and endgame phases and ducks while casting. Audio unlocks after the first click. Saves, decks and settings stay on this device.')}</p>${button('settings-done',T('完成','Done'),'primary')}</div>`);}
function showLog(){modal(`<div class="log-content"><div class="eyebrow">BATTLE LOG</div><h2>${T('战斗记录','Battle log')}</h2>${game.s?`<div class="event-list">${game.s.log.filter(e=>e.secret===undefined||e.secret===0||online?.isSpectator()).slice().reverse().map(e=>`<div class="log-event ${e.type}"><time>R${e.round} · ${LN(e.lane)}</time><span>${esc(L(e.text))}</span></div>`).join('')}</div>`:`<p>${T('尚无对局记录。','No events logged yet.')}</p>`}</div>`,true);}
async function action(name,el){if(ui.busy)return;if(online?.action(name,el,{plan:getDeploymentPlan,toast}))return;if(bridge?.action(name,el,game))return;if(ui.intro&&name!=='skip-intro'&&name!=='sound')return;try{if(!sound.ctx&&name!=='sound')sound.start().catch(()=>{});if(['lobby','decks','collection'].includes(name)){if(ui.route==='battle')write('artifact.match',game.s);clearTimeout(aiTimer);ui.route=name;ui.selection=null;ui.inspect=null;ui.filter={q:'',color:'All',type:'All',expansion:ui.filter.expansion};sound.scene='menu';render();return;}
 switch(name){
 case 'skip-intro':ui.intro=false;render();scheduleAI();break;
 case 'start':start();break;
 case 'resume':{const saved=read('artifact.match',null);if(!saved||saved.version!==1)throw Error(T('未找到兼容的存档','No compatible save found'));game=new Game(CARDS);game.s=saved;game.s.events=[];ui.focus=game.s.phase==='deploy'?null:game.s.lane;deploymentPlan=null;ui.deploySelected=null;ui.route='battle';ui.busy=false;ui.intro=false;ui.lastEnemyCast=game.s.log.slice().reverse().find(e=>(e.type==='card'||e.type==='ability')&&e.owner===1)||null;ui.lastCast=game.s.log.slice().reverse().find(e=>e.type==='card'||e.type==='ability')||null;render();scheduleAI();break;}
 case 'pass':if(!ui.busy){game.pass(0);commit();}break;
 case 'hand-prev':case 'hand-next':$('.hand-scroll').scrollBy({left:(name==='hand-next'?1:-1)*260,behavior:'smooth'});break;
 case 'cancel':ui.selection=null;render();break;
 case 'sound':settings.muted=!settings.muted;sound.enabled=!settings.muted;await sound.start();sound.setVolumes();write('artifact.settings',settings);render();scheduleAI();break;
 case 'settings':showSettings();break;case 'help':help();break;case 'about':about();break;case 'log':showLog();break;
 case 'close-modal':closeModal();break;
 case 'settings-done':write('artifact.settings',settings);closeModal();render();scheduleAI();break;
 case 'card-audio':showAudio(el.dataset.key);break;
 case 'card-info':showCard(el.dataset.key);break;
 case 'focus-lane':boardTransition(Number(el.dataset.lane));break;case 'unfocus':boardTransition(null);break;
 case 'target-lane':selectTarget(Number(el.dataset.lane));break;
 case 'hero-skill':case 'unit-ability':{const u=game.get(el.dataset.id);if(!u)break;ui.inspect=u.uid;ui.inspectSkill=true;render();break;}
 case 'activate':ui.inspect=null;ui.inspectSkill=false;chooseAction('ability',Number(el.dataset.id),el.dataset.key);break;
 case 'close-inspector':ui.inspect=null;ui.inspectSkill=false;render();break;
 case 'roster':{const u=game.get(el.dataset.id);if(u){ui.inspect=u.uid;render();}break;}
 case 'improvement':{const uid=Number(el.dataset.id),p=Number(el.dataset.owner),l=Number(el.dataset.lane),i=game.imps(p,l).find(i=>i.uid===uid);if(ui.selection?.spec[ui.selection.targets.length]?.kind==='improvement'){selectTarget(uid);break;}if(p===0&&l===game.s.lane&&game.abilities(i).length)chooseAction('ability',uid,i.k);else showCard(i.k);break;}
 case 'buy':{const card=el.closest('.shop-stall').querySelector('.game-card'),from=card.getBoundingClientRect(),k=game.s.players[0].shop[el.dataset.slot];game.buy(0,el.dataset.slot);commit();const target=[...document.querySelectorAll('.hand-cards .game-card')].findLast(c=>c.dataset.card===k);if(target)ArtifactScene.purchase($('#fx-layer'),target,from);break;}
 case 'hold':game.hold(0);sound.play('hold');commit();break;
 case 'toggle-shop':ui.shopHidden=!ui.shopHidden;render();break;
 case 'finish-shop':ui.shopHidden=false;game.aiShop(1);game.startRound();deploymentPlan=null;ui.deploySelected=null;ui.focus=null;commit();break;
 case 'select-deploy':if(game.s.phase==='deploy'){ui.deploySelected=Number(el.dataset.id);sound.play('select');render();}break;
 case 'assign-deploy':if(ui.deploySelected)assignDeployment(ui.deploySelected,Number(el.dataset.lane));break;
 case 'unassign-deploy':if(ui.deploySelected)assignDeployment(ui.deploySelected,null);break;
 case 'reset-deploy':getDeploymentPlan().reset();ui.deploySelected=null;write('artifact.match',game.s);render();break;
 case 'finish-deploy':getDeploymentPlan().confirm();deploymentPlan=null;ui.deploySelected=null;ui.focus=0;commit();break;
 case 'save-match':write('artifact.match',game.s);toast(T('对局已保存，下次可继续','Match saved — you can continue later'));break;
 case 'surrender':modal(`<h2>${T('结束本场对局？','End this match?')}</h2><p>${bridge?T('撤退后可在营地调整构筑，保留关前成长。','Retreat to camp to adjust your deck — progress is kept.'):T('认输后将由夜魇获胜。','Conceding gives Dire the win.')}</p><div class="lobby-actions">${button('close-modal',T('继续对战','Keep playing'),'secondary')}${button('confirm-surrender',T('确认认输','Concede'),'primary')}</div>`);break;
 case 'confirm-surrender':game.s.winner=1;game.s.phase='ended';commit();break;
 case 'filter-color':ui.filter.color=el.dataset.color;render();break;
 case 'deck-add':addDeck(el.dataset.key);break;case 'deck-remove':addDeck(el.dataset.key,true);break;
 case 'hero-order':{const i=Number(el.dataset.index);if(i>0)[ui.builder.heroes[i-1],ui.builder.heroes[i]]=[ui.builder.heroes[i],ui.builder.heroes[i-1]];else ui.builder.heroes.push(ui.builder.heroes.shift());render();break;}
 case 'deck-save':{const errs=game.validateDeck(ui.builder);if(errs.length)throw Error(errs[0]);ui.builder.id='custom';write('artifact.customDeck',ui.builder);ui.deckId='custom';toast(T('牌组已保存，可在对战菜单选择','Deck saved — selectable from the play menu'));break;}
 case 'copy-opponent-deck':{if(game.s?.phase!=='ended'||online?.isSpectator())break;const d=game.s.deckSpecs?.[1];if(!d||game.validateDeck(d).length)throw Error(T('此对手构筑无法用于标准对战','This opponent build is not legal for standard play'));const saved=ArtifactDeckShare.saveDeck(d);toast(T('已收藏「','Saved “')+saved.name+T('」，可在单人或联机选择','” — usable in solo and online'));break;}
 case 'deck-share':ArtifactDeckShare.share(ui.builder,d=>game.validateDeck(d));break;
 case 'deck-share-import':ArtifactDeckShare.importDeck({cards:CARDS,validate:d=>game.validateDeck(d),onConfirm:d=>{ui.builder={name:String(d.name||T('分享构筑','Shared build')).slice(0,40),heroes:d.heroes,main:d.main,items:d.items,id:'custom'};render();toast(T('分享构筑已载入编辑器；原有保存未更改','Shared build loaded into the editor; your saved deck is unchanged'));}});break;
 case 'deck-export':saveFile('artifact-deck.json',{format:'artifact-threefold-v1',...ui.builder});toast(T('牌组已导出','Deck exported'));break;
 case 'deck-import':modal(`<h2>${T('导入牌组','Import deck')}</h2><p>${T('粘贴本项目导出的 JSON 牌组。','Paste a JSON deck exported from this app.')}</p><textarea id="import-deck" rows="10" spellcheck="false" placeholder="{ &quot;name&quot;: &quot;${T('我的牌组','My deck')}&quot;, &quot;heroes&quot;: […], … }"></textarea>${button('confirm-import',T('导入','Import'),'primary')}`);break;
 case 'confirm-import':{const raw=$('#import-deck').value;if(raw.length>30000)throw Error(T('牌组文件过大','Deck file too large'));const d=JSON.parse(raw);const errs=game.validateDeck(d);if(errs.length)throw Error(errs[0]);ui.builder={name:String(d.name||T('导入牌组','Imported deck')).slice(0,40),heroes:d.heroes,main:d.main,items:d.items,id:'custom'};closeModal();render();toast(T('已导入，可继续编辑或保存','Imported — edit further or save'));break;}
 case 'deck-clear':modal(`<h2>${T('清空当前编辑中的牌组？','Clear the deck being edited?')}</h2><p>${T('已保存的牌组仍可从对战菜单读取。','Saved decks remain available in the play menu.')}</p>${button('confirm-clear',T('清空','Clear'),'primary')} ${button('close-modal',T('取消','Cancel'),'secondary')}`);break;
 case 'confirm-clear':ui.builder={name:T('新的牌组','New deck'),heroes:[],main:[],items:[]};render();break;
 case 'deck-load':modal(`<h2>${T('载入预设牌组','Load a preset deck')}</h2><div class="preset-list">${allDecks().map(d=>button('preset-load',`<strong>${esc(pick(d,'name'))}</strong><small>${esc(pick(d,'desc')||T('已保存构筑','Saved build'))}</small>`,'preset-button',`data-id="${d.id}"`)).join('')}</div>`);break;
 case 'preset-load':ui.builder=clone(chosen(el.dataset.id));render();break;
 }
 }catch(e){console.error(e);toast(e.message||T('操作失败，请重试','Operation failed — please retry'));sound.play('error');}}
document.addEventListener('click',e=>{if(ui.busy)return;if(ui.intro&&!e.target.closest('[data-action="skip-intro"]'))return;const a=e.target.closest('[data-action]');if(a){e.stopPropagation();action(a.dataset.action,a);return;}const h=e.target.closest('[data-hand]');if(h){const card=game.s.players[0].hand.find(c=>c.uid===Number(h.dataset.hand));if(e.detail===2||e.detail===0)chooseAction('play',h.dataset.hand,card.k);else{ui.selection=null;$('.selection-banner')?.remove();document.querySelectorAll('.targetable,.lane-target').forEach(v=>v.classList.remove('targetable','lane-target'));document.querySelectorAll('.hand-reading').forEach(v=>v.classList.remove('hand-reading'));h.classList.add('hand-reading');toast(T('双击此牌，或拖到战场释放；单击不会出牌','Double-click or drag to the board to play — single click only inspects'));}return;}if(ui.route!=='battle')return;const uel=e.target.closest('[data-unit]');if(uel){const u=game.get(uel.dataset.unit);if(ui.selection?.spec[ui.selection.targets.length]?.kind==='position'&&u.owner===0){const slot=uel.closest('[data-slot]');selectTarget({lane:Number(slot.dataset.lane),pos:Number(slot.dataset.slot)});return;}if(!game.selectable(u))return;if(ui.selection){if(validUnit(u))selectTarget(u.uid);else toast(T('这个单位不符合当前目标条件','That unit does not match the current target'));}else{ui.inspect=u.uid;render();}return;}const slot=e.target.closest('[data-slot]');if(slot&&ui.selection?.spec[ui.selection.targets.length]?.kind==='position'&&Number(slot.dataset.owner)===0)selectTarget({lane:Number(slot.dataset.lane),pos:Number(slot.dataset.slot)});});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='deck-select'){ui.deckId=t.value;render();}if(t.id==='opponent-select')ui.opponentId=t.value;if(t.id==='expansion-filter'){ui.filter.expansion=t.value;render();}if(t.id==='type-filter'){ui.filter.type=t.value;render();}if(t.id==='game-speed')settings.speed=Number(t.value);if(t.id==='forecast-setting')settings.showForecast=t.checked;});
let searchTimer;document.addEventListener('input',e=>{const t=e.target;if(t.id==='card-search'){ui.filter.q=t.value;const pos=t.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const s=$('#card-search');s.focus();try{s.setSelectionRange(pos,pos);}catch{}},160);}if(t.id==='deck-name')ui.builder.name=t.value;if(t.id==='music-volume'){settings.music=Number(t.value);sound.music=settings.music;sound.setVolumes();}if(t.id==='effects-volume'){settings.effects=Number(t.value);sound.effects=settings.effects;sound.setVolumes();}});
document.addEventListener('keydown',e=>{if(ui.intro){if(e.key==='Escape'||e.code==='Space'||e.key==='Enter'){e.preventDefault();action('skip-intro',{});}return;}if(ui.busy){if(e.code==='Space')e.preventDefault();return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='Escape'){if($('#modal')?.open)return;ui.deploySelected=null;ui.selection=null;ui.inspect=null;render();return;}if($('#modal')?.open)return;if(e.key==='Enter'&&(e.target.matches('[data-hand]')||e.target.matches('[data-unit]'))){e.preventDefault();e.target.click();}if(ui.route!=='battle')return;if(e.code==='Space'){e.preventDefault();if(game.s.turn===0&&game.s.phase==='action'&&!ui.busy)action('pass',{});}if('123'.includes(e.key)){boardTransition(Number(e.key)-1);}if(e.key==='0'){boardTransition(null);}});
const tooltipSelector='[data-hero-skill],[data-equipment-slot],[data-equipment-abilities],[data-card]';
function tooltipContent(el){
 const unitId=el.closest('[data-unit]')?.dataset.unit||el.closest('[data-deploy-hero]')?.dataset.deployHero;
 const u=unitId?game.get(Number(unitId)):null;
 if(el.hasAttribute('data-hero-skill')&&u){
  const a=heroSkills(u)[Number(el.dataset.heroSkill)];if(!a)return '';
  const active=game.abilities(u).find(v=>v.k===(a.k||u.k));
  const status=a.type==='active'?abilityBlocked(u,active||{k:a.k||u.k,remaining:0})||T('可以使用 · 点击查看并施放','Ready · click to view and cast'):game.enabled(u)?T('满足条件时自动生效，无需点击施放','Triggers automatically — no click needed'):T('当前失效：阵亡、沉默或眩晕','Inactive while dead, silenced or stunned');
  return `<div class="tooltip-ability-heading"><img src="${esc(a.icon||C[u.k].art)}" alt=""><div><strong>${esc(ABNAME(a))}</strong><small>${esc(cardName(C[u.k]))} · ${a.type==='active'?T('主动技能','Active'):T('被动技能','Passive')}</small></div></div><div><p>${esc(ABDESC(a))}</p>${a.type==='active'?`<small>${T('基础冷却','Base cooldown')} ${a.cooldown} ${T('回合','rounds')}${active?.remaining?' · '+T('剩余 '+active.remaining+' 回合',active.remaining+' remaining'):''}</small>`:''}<p class="tooltip-stats">${esc(status)}</p></div>`;
 }
 if(el.hasAttribute('data-equipment-abilities')&&u){
  const abilities=game.abilities(u).filter(a=>!heroSkills(u).some(s=>(s.k||u.k)===a.k));
  return `<div class="tooltip-ability-heading"><img src="${C[u.k].art}" alt=""><div><strong>${T('装备与主动技能','Equipment & actives')}</strong><small>${esc(cardName(C[u.k]))} · ${T('点击查看并施放','click to view and cast')}</small></div></div><div>${abilities.map(a=>`<section class="tooltip-equipment-ability"><strong>${esc(C[a.k]?cardName(C[a.k]):(a.name?T(a.name,a.en||a.name):T('主动技能','Active ability')))}</strong><p>${esc(C[a.k]?cardText(C[a.k]):(a.text||''))}</p><small>${esc(abilityBlocked(u,a)||T('可以使用','Ready'))}${a.remaining?' · '+T('剩余','remaining ')+a.remaining+' '+T('回合','rounds'):''}</small></section>`).join('')}</div>`;
 }
 const c=C[el.dataset.card];
 if(!c&&el.hasAttribute('data-equipment-slot')){
  const slot=el.dataset.equipmentSlot,label=slot==='Weapon'?T('武器','Weapon'):slot==='Armor'?T('护甲','Armor'):T('饰品','Accessory');
  return `<div class="tooltip-empty-slot"><strong>${label}${T('栏 · 未装备',' slot · empty')}</strong><p>${T('为这名英雄装备','Equip a ')}${label}${T('后，将在这里显示物品及其效果。',' to this hero and its effects will show here.')}</p></div>`;
 }
 if(!c)return '';
 // Preview the equipped item itself, not its owner's hero statistics.
 const stat=u&&['Hero','Creep'].includes(c.type)?game.stats(u):null;
 const ability=u&&c.type==='Item'?game.abilities(u).find(a=>a.k===c.key):null;
 return `<img src="${c.art}" alt=""><div><strong>${esc(cardName(c))}</strong><small>${esc(T(c.en||'',c.name))} · ${TN(c.type)} · ${CN(c.color)}${c.type==='Item'?' · '+c.gold+' '+T('金币','gold'):c.type==='Hero'?'':' · '+c.mana+' '+T('魔力','mana')}</small>${stat?`<p class="tooltip-stats">${T('攻击','Attack')} ${stat.attack} · ${T('护甲','Armor')} ${stat.armor} · ${T('生命','Health')} ${u.alive?stat.hp:stat.health}/${stat.health}</p>`:''}<p>${esc(cardText(c)||T('无额外技能。','No additional abilities.'))}</p>${ability?`<p class="tooltip-stats">${esc(abilityBlocked(u,ability)||T('装备主动技能可以使用','Item active is ready'))}</p>`:''}${stat&&u?.hero?deploymentEquipmentHTML(u):''}</div>`;
}
let tooltipTimer;
function hideCardTooltip(){clearTimeout(tooltipTimer);$('#card-tooltip')?.classList.remove('visible');}
// Actual pointer input wins over viewport size or the presence of a touchscreen.
function cardPointerInput(e){
 if(!e.pointerType)return;
 const mouse=e.pointerType==='mouse';
 document.body.classList.toggle('mouse-card-input',mouse);
 document.body.classList.toggle('touch-card-input',!mouse);
 if(mouse)document.body.classList.remove('touch-hand-input');else hideCardTooltip();
}
document.addEventListener('pointerover',cardPointerInput,true);
document.addEventListener('pointermove',cardPointerInput,true);
document.addEventListener('pointerdown',cardPointerInput,true);
document.addEventListener('mouseover',e=>{
 const el=e.target.closest(tooltipSelector);
 if(!el||el===e.relatedTarget?.closest?.(tooltipSelector)||$('#modal')?.open||document.body.classList.contains('touch-card-input'))return;
 hideCardTooltip();
 tooltipTimer=setTimeout(()=>{
  const tt=$('#card-tooltip');
  if(!tt||!el.isConnected||$('#modal')?.open||document.body.classList.contains('touch-card-input'))return;
  const content=tooltipContent(el);if(!content)return;
  tt.innerHTML=content;
  tt.classList.add('visible');
  const r=el.getBoundingClientRect(),w=tt.offsetWidth,h=tt.offsetHeight;
  let left=r.right+14,top=r.top;
  if(el.closest('.hand-zone')){left=r.left+(r.width-w)/2;top=r.top-h-12;}
  else if(left+w>innerWidth-12)left=r.left-w-14;
  tt.style.left=Math.max(12,Math.min(innerWidth-w-12,left))+'px';
  tt.style.top=Math.max(12,Math.min(innerHeight-h-12,top))+'px';
 },240);
});
document.addEventListener('mouseout',e=>{const el=e.target.closest(tooltipSelector);if(el&&el!==e.relatedTarget?.closest?.(tooltipSelector))hideCardTooltip();});
document.addEventListener('dragstart',hideCardTooltip,true);
document.addEventListener('pointerdown',hideCardTooltip,true);
