window.addEventListener('resize',hideCardTooltip);
document.addEventListener('scroll',hideCardTooltip,true);
document.addEventListener('dragstart',e=>{const h=e.target.closest('[data-hand]');if(!h)return;const card=game.s.players[0].hand.find(v=>v.uid===Number(h.dataset.hand));if(game.canPlay(0,card)){e.preventDefault();toast(game.canPlay(0,card));return;}ui.dragAccepted=false;e.dataTransfer.setData('text/plain',h.dataset.hand);e.dataTransfer.effectAllowed='move';const spec=game.targets(card.k,0);ui.selection={kind:'play',id:card.uid,k:card.k,spec,targets:[]};const board=$('.board');if(board){board.innerHTML=Array.from({length:game.s.activeLanes||3},(_,l)=>laneHTML(l)).join('');layoutBoard();}});
document.addEventListener('dragover',e=>{if(ui.selection&&(e.target.closest('[data-unit]')||e.target.closest('[data-slot]')||e.target.closest('.lane')))e.preventDefault();});
document.addEventListener('drop',e=>{if(!ui.selection)return;e.preventDefault();ui.dragAccepted=true;const se=ui.selection,s=se.spec[se.targets.length],u=e.target.closest('[data-unit]'),slot=e.target.closest('[data-slot]'),l=e.target.closest('.lane');if(!s){if(l&&Number(l.dataset.lane)===game.s.lane){game.play(0,se.id,[]);commit();}else{ui.selection=null;render();}return;}if(s.kind==='unit'&&u&&validUnit(game.get(u.dataset.unit)))selectTarget(Number(u.dataset.unit));else if(s.kind==='position'&&slot&&slot.dataset.owner==='0')selectTarget({lane:Number(slot.dataset.lane),pos:Number(slot.dataset.slot)});else if(s.kind==='lane'&&l)selectTarget(Number(l.dataset.lane));else if(s.kind==='improvement'&&e.target.closest('.improvement'))selectTarget(Number(e.target.closest('.improvement').dataset.id));else{render();toast(T('请选择亮起的目标继续出牌','Pick a highlighted target to continue'));}});
document.addEventListener('dragend',()=>{if(ui.selection){if(!ui.dragAccepted)ui.selection=null;render();}});
document.addEventListener('wheel',e=>{const hand=e.target.closest('.hand-wrap');if(!hand)return;const scroll=hand.closest('.hand-scroll');if(scroll.scrollWidth>scroll.clientWidth){e.preventDefault();scroll.scrollLeft+=e.deltaY||e.deltaX;}},{passive:false});
document.addEventListener('play',e=>{if(!e.target.matches?.('.audio-audition'))return;document.querySelectorAll('.audio-audition').forEach(a=>{if(a!==e.target)a.pause();});sound.previewing=true;sound.setVolumes();},true);
for(const event of ['pause','ended'])document.addEventListener(event,e=>{if(e.target.matches?.('.audio-audition')){sound.previewing=[...document.querySelectorAll('.audio-audition')].some(a=>!a.paused&&!a.ended);sound.setVolumes();}},true);
