I18N&&I18N.onChange&&I18N.onChange(()=>render());
if(online){ui.route='battle';ui.focus=game.s.phase==='deploy'?null:game.s.lane;ui.intro=false;ui.lastEnemyCast=game.s.log.slice().reverse().find(e=>(e.type==='card'||e.type==='ability')&&e.owner===1)||null;online.mount(window.ArtifactApp);}
